from typing import List, Tuple

def f(N: int, M: int, C: int, connections: List[Tuple[int, int, int]]):
    graph_commutator_cost = 0
    W = [-1] * (N + 1)

    heap = []

    class GraphNode:
        def __init__(self, value):
            self.value = value
            self.d = float('inf')

        def __lt__(self, other):
            return self.d < other.d

    class DisjointSet:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n

        def find(self, x, paths):
            paths.append(x)
            if x == self.parent[x]:
                return x
            self.parent[x] = self.find(self.parent[x], paths)
            return self.parent[x]

        def union(self, x, y):
            x_root = self.find(x, [])
            y_root = self.find(y, [])
            if x_root == y_root:
                return
            if self.rank[x_root] < self.rank[y_root]:
                self.parent[x_root] = y_root
            elif self.rank[x_root] >  self.rank[y_root]:
                self.parent[y_root] = x_root
            else:
                self.parent[y_root] = x_root
                self.rank[x_root] += 1

    for a, b, d in connections:
        if W[a] == -1 or W[b] == -1:
            graph_commutator_cost += d
        else:
            graph_commutator_cost += d * 2

        W[a] = b
        W[b] = a

    heap_root = GraphNode(0)
    heap.append(heap_root)

    disjoint_set = DisjointSet(N + 1)

    while heap:
        current_node = heap.pop(0)
        # Extract min heap node
        current_node.d = -current_node.d
        if current_node.value == W[1] and W[1]!= -1:
            break
        for neighbor, neighbor_weight in enumerate(W):
            if neighbor!= current_node.value and neighbor_weight!= -1 and neighbor!= current_node.value and W[neighbor]!=0:
                graph_node = GraphNode(1)
                graph_node.value = neighbor
                graph_node.d = neighbor_weight
                heap.append(graph_node)
                graph_node.d = -graph_node.d #Also change this so heap sort
                disjoint_set.union(current_node.value, neighbor)

    for a, b, d in connections:
        graph_commutator_cost -= d
        if disjoint_set.find(a, []) == disjoint_set.find(b, []):
            graph_commutator_cost += (d * 2)
    return graph_commutator_cost * min(C, 1)
